cmsis-pack-trace-snippet.debugvars:
// ETF
__var ETF___INSTANCE_INDEX___ADDRESS       = 0xE0042000;
__var ETF___INSTANCE_INDEX___AP            = 0x00000000;
__var ETF___INSTANCE_INDEX___PSCR_CircularBuffer = 0x7; // Short sync period to reduce discarded trace data; hardware default is 0xA

sequence.block:
// Helper variables
__var savedAP = __ap;
__var ffcrValue = 0x00000000;
__var etfStatus = 0x00000000;

Message(0, "Begin CS_ETF___INSTANCE_INDEX___Configure_HWFIFO @0x%08X, AP 0x%08X", ETF___INSTANCE_INDEX___ADDRESS, ETF___INSTANCE_INDEX___AP);
__ap = ETF___INSTANCE_INDEX___AP;                             // Set AP

// Configure ETF to HW FIFO for Sync Trace
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000000);  // Disable ETF before configuring
etfStatus = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x00C);

// Configure
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x028, 0x00000002);  // Set HW FIFO Mode
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x034, 0x00000000);  // Watermark: Set threshold vacancy to 0 to use full buffer
ffcrValue  = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x304);
ffcrValue |= 0x00000003;                                      // FFCR: Enable Formatter and Trigger Insertion
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x308, 0x00000000);  // Clear PSCR, use other components for periodic sync requests

Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000001);  // Enable ETF

// Helper variables
__var savedAP = __ap;
__var ffcrValue = 0x00000000;
__var etfStatus = 0x00000000;

Message(0, "Begin CS_ETF___INSTANCE_INDEX___Configure_CircularBuffer @0x%08X, AP 0x%08X", ETF___INSTANCE_INDEX___ADDRESS, ETF___INSTANCE_INDEX___AP);
__ap = ETF___INSTANCE_INDEX___AP;                                     // Set AP

// Configure ETF for circular-buffer trace capture.
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000000);          // Disable ETF before configuring
etfStatus = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x00C);

// Helper variables
__var ffcrValue = 0x00000000;
__var savedAP = __ap;

Message(0, "Begin CS_ETF___INSTANCE_INDEX___Capture_CircularBuffer @0x%08X, AP 0x%08X", ETF___INSTANCE_INDEX___ADDRESS, ETF___INSTANCE_INDEX___AP);

__ap = ETF___INSTANCE_INDEX___AP;                                     // Set AP
ffcrValue  = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x304);
ffcrValue |= 0x00000003;                                              // FFCR: Enable Formatter and Trigger Insertion
ffcrValue |= 0x00000400;                                              // FFCR: Insert trigger marker on flush completion (TrigFl)
ffcrValue |= 0x00001020;                                              // Flush and Stop Formatter on Trigger (FOnTrig + StopFl)
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x308, ETF___INSTANCE_INDEX___PSCR_CircularBuffer);  // Set PSCR
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x018, 0x00000000);          // Init RwP
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x014, 0x00000000);          // Init RRP
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000001);          // Enable ETF
__ap = savedAP;

Message(0, "End CS_ETF___INSTANCE_INDEX___Capture_CircularBuffer @0x%08X, AP 0x%08X", ETF___INSTANCE_INDEX___ADDRESS, ETF___INSTANCE_INDEX___AP);

// Helper variables
__var savedAP     = __ap;
__var ffcrValue   = 0x00000000;
__var etfStatus   = 0x00000000;

Message(0, "Begin CS_ETF___INSTANCE_INDEX___Flush @0x%08X, AP 0x%08X", ETF___INSTANCE_INDEX___ADDRESS, ETF___INSTANCE_INDEX___AP);

__ap = ETF___INSTANCE_INDEX___AP;  // Set AP

// Flush the ETF formatter and stop capture.
ffcrValue = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x304);
ffcrValue &= ~(0x00001460);    // Clear FOnTrig, StopFl, FOnMan and TrigFl; do not insert a trigger packet on manual flush
ffcrValue |= 0x00001000;           // Stop after the manual flush completes
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);
ffcrValue |= 0x00000040;           // Trigger manual flush
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);

// Disable ETF after flush until next run/step
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x020, 0x00000000);
etfStatus = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x00C);

// Helper variables
__var savedAP       = __ap;
__var etfStatus     = 0x00000000;
__var bufferSize    = 0x00000000;
__var readPointer   = 0x00000000;
__var writePointer  = 0x00000000;
__var bytesToRead   = 0x00000000;
__var bytesStreamed = 0x00000000;

Message(0, "Begin CS_ETF___INSTANCE_INDEX___Read_CircularBuffer @0x%08X, AP 0x%08X", ETF___INSTANCE_INDEX___ADDRESS, ETF___INSTANCE_INDEX___AP);

__ap = ETF___INSTANCE_INDEX___AP; // Set AP

// TMC RSZ is expressed in 32-bit words. RRP and RWP are byte offsets.
bufferSize   = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x004) * 4;
etfStatus    = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x00C);
readPointer  = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x014);
writePointer = Read32(ETF___INSTANCE_INDEX___ADDRESS + 0x018);

control.block:
// STS.Full distinguishes a wrapped/full buffer from an empty buffer
// when the read and write pointers are equal.
Message(0, "ETF Circular Buffer wrapped around");
bytesToRead = bufferSize;
// RWP identifies the oldest retained trace after the buffer wraps.
Write32(ETF___INSTANCE_INDEX___ADDRESS + 0x014, writePointer); // Rebase RRP for chronological output

// Read repeatedly from the TMC RRD register. The TMC advances RRP.
BufferRead(0, 0, ETF___INSTANCE_INDEX___ADDRESS + 0x010, bytesToRead, 32);
// Stream to single unnamed trace buffer in system by default, insert name if multiple
// named buffers specified in PDSC. Decide which xxx_Read_Buffer sequence to call based
// on TraceBufferSelected().
bytesStreamed = BufferStreamOut(0, 0, bytesToRead, "", 1, 0);
Message(0, "Streamed %u of %u ETF trace bytes", bytesStreamed, bytesToRead);
